/* No coloured bar down the left edge. Tone is carried
   by a full danger hairline, a tinted head band, the danger icon tile and the
   heading, so the box reads as an error from any edge. */

.summary {
  overflow: hidden;
  border: 1px solid var(--danger-line);
  border-radius: var(--r-md);
  background: var(--surface-solid);
  box-shadow: var(--shadow-lift);
  outline: none;
}

.summary:focus-visible {
  box-shadow: var(--focus-ring), var(--shadow-lift);
}

/* ── Head: tinted band, icon tile, heading and how-to line ─────────────── */

.head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  background: var(--danger-fill);
  border-bottom: 1px solid var(--danger-line);
}

/* The toast tile's form: the danger gesture in miniature, white glyph.
   White on --danger-base-solid is 4.6:1; the glyph only needs 3:1. */
.tile {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 30px;
  height: 30px;
  border-radius: var(--r-sm);
  background: var(--danger-gradient);
  box-shadow: var(--glow-danger), var(--shadow-specular-dark);
  color: var(--ink-inverse);
}

.heading {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.title {
  margin: 0;
  font-size: var(--text-card-title);
  font-weight: 700;
  line-height: 1.35;
  color: var(--danger-ink);
}

.lead {
  margin: 0;
  font-size: var(--text-caption);
  line-height: 1.45;
  color: var(--ink-secondary);
}

/* ── Entries: one row per error, each a jump link ─────────────────────── */

.list {
  margin: 0;
  padding: 4px 0;
  list-style: none;
}

.list li + li {
  border-top: 1px solid var(--line-soft);
}

.item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 9px 16px;
  font-size: var(--text-small);
  font-weight: 700;
  line-height: 1.5;
  color: var(--danger-ink);
  text-decoration: none;
  transition:
    background-color var(--dur) var(--ease),
    color var(--dur) var(--ease);
}

/* Numbered like the count in the heading, so "Fix 3 things" maps onto 1–3. */
.index {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  min-width: 20px;
  height: 20px;
  margin-top: 0.5px;
  padding: 0 5px;
  border-radius: var(--r-2xs);
  background: var(--danger-fill);
  box-shadow: inset 0 0 0 1px var(--danger-line);
  font-size: var(--text-micro);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.message {
  flex: 1;
  min-width: 0;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  text-decoration-color: rgba(var(--rgb-danger), 0.45);
}

.go {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 4px;
  margin-top: 1px;
  font-size: var(--text-caption);
  font-weight: 700;
  color: var(--ink-muted);
  opacity: 0;
  transition: opacity var(--dur) var(--ease);
}

.item:hover {
  background: var(--danger-fill);
}

.item:hover .message {
  text-decoration-color: currentColor;
}

.item:hover .go,
.item:focus-visible .go {
  opacity: 1;
}

.item:active {
  background: rgba(var(--rgb-danger), 0.14);
}

.item:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--focus-color);
  background: var(--danger-fill);
}

@media (hover: none) {
  .go {
    opacity: 1;
  }
}

@media (forced-colors: active) {
  .summary {
    border: 2px solid CanvasText;
  }

  .item:focus-visible {
    outline: 2px solid Highlight;
  }
}

@media print {
  .summary {
    box-shadow: none;
    border: 1px solid #000;
  }

  .go {
    display: none;
  }
}

"use client";

import { useEffect, useId, useRef } from "react";
import { focusableWithin } from "../_internal/position";
import { IconAlertCircle, IconArrowRight } from "../Icon/Icon";
import styles from "./ErrorSummary.module.css";

export type FormError = {
  /** The Field id (the control's id, or the fieldset id for a group). */
  id: string;
  message: string;
};

export type ErrorSummaryProps = {
  errors: ReadonlyArray<FormError>;
  title?: string;
  /**
   * Change this (e.g. a submit counter) to move focus to the summary again.
   * Focus moves on mount and whenever it changes.
   */
  focusKey?: number | string;
  className?: string;
};

/**
 * Shown at the top of a form after a failed submit. Takes focus so screen
 * reader users hear the count, and each entry jumps to its field. Render
 * nothing (not an empty box) when there are no errors. No left accent bar
 *: tone is the hairline, head band, tile and heading.
 */
export function ErrorSummary(props: ErrorSummaryProps) {
  if (props.errors.length === 0) return null;
  return <SummaryBox {...props} />;
}

// Mounted only while there are errors, so focus moves when it first appears
// and on each focusKey change, but not as errors clear one by one (which
// would pull focus out of the field being corrected).
function SummaryBox({ errors, title, focusKey, className }: ErrorSummaryProps) {
  const ref = useRef<HTMLDivElement>(null);
  const titleId = `error-summary-${useId()}`;
  const count = errors.length;

  useEffect(() => {
    ref.current?.focus();
  }, [focusKey]);

  const jump = (id: string) => {
    const el = document.getElementById(id);
    if (!el) return;
    const target = el.matches("input, select, textarea, button") ? el : (focusableWithin(el)[0] ?? el);
    el.scrollIntoView({ block: "center", behavior: "smooth" });
    target.focus({ preventScroll: true });
  };

  return (
    <div data-slot="error-summary" ref={ref} role="alert" tabIndex={-1} className={`${styles.summary} ${className ?? ""}`} aria-labelledby={titleId}>
      <div className={styles.head}>
        <span className={styles.tile} aria-hidden="true">
          <IconAlertCircle size={17} />
        </span>
        <div className={styles.heading}>
          <p id={titleId} className={styles.title}>
            {title ?? (count === 1 ? "Fix 1 thing to continue" : `Fix ${count} things to continue`)}
          </p>
          <p className={styles.lead}>Select a problem to go straight to its field.</p>
        </div>
      </div>
      <ol className={styles.list}>
        {errors.map((e, i) => (
          <li key={`${e.id}-${e.message}`}>
            <a
              href={`#${e.id}`}
              className={styles.item}
              onClick={(ev) => {
                ev.preventDefault();
                jump(e.id);
              }}
            >
              <span className={styles.index} aria-hidden="true">
                {i + 1}
              </span>
              <span className={styles.message}>{e.message}</span>
              <span className={styles.go} aria-hidden="true">
                Go to field <IconArrowRight size={13} />
              </span>
            </a>
          </li>
        ))}
      </ol>
    </div>
  );
}
